-- Read-only production metadata before/after apply or rollback.
BEGIN READ ONLY;
SELECT jsonb_build_object(
 'policies',(SELECT coalesce(jsonb_agg(to_jsonb(p) ORDER BY tablename,policyname),'[]'::jsonb) FROM pg_policies p WHERE schemaname='public' AND tablename IN ('event_participants','rounds','matches','match_players','match_results')),
 'acl',(SELECT jsonb_agg(jsonb_build_object('table',c.relname,'grantee',CASE WHEN grantee=0 THEN 'PUBLIC' ELSE grantee::regrole::text END,'grantor',grantor::regrole::text,'privilege',privilege_type,'grantable',is_grantable) ORDER BY c.relname,grantee,privilege_type) FROM pg_class c CROSS JOIN LATERAL aclexplode(c.relacl) WHERE c.oid IN ('public.event_participants'::regclass,'public.rounds'::regclass,'public.matches'::regclass,'public.match_players'::regclass,'public.match_results'::regclass)),
 'rls',(SELECT jsonb_agg(jsonb_build_object('table',relname,'enabled',relrowsecurity) ORDER BY relname) FROM pg_class WHERE oid IN ('public.event_participants'::regclass,'public.rounds'::regclass,'public.matches'::regclass,'public.match_players'::regclass,'public.match_results'::regclass)),
 'counts',jsonb_build_object('event_participants',(SELECT count(*) FROM public.event_participants),'rounds',(SELECT count(*) FROM public.rounds),'matches',(SELECT count(*) FROM public.matches),'match_players',(SELECT count(*) FROM public.match_players),'match_results',(SELECT count(*) FROM public.match_results)),
 'privileges',(SELECT jsonb_agg(jsonb_build_object('table',t,'role',r,'privilege',p,'allowed',has_table_privilege(r,'public.'||t,p)) ORDER BY t,r,p)
 FROM unnest(ARRAY['event_participants','rounds','matches','match_players','match_results']) ts(t)
 CROSS JOIN unnest(ARRAY['anon','authenticated','service_role']) rs(r)
 CROSS JOIN unnest(ARRAY['SELECT','INSERT','UPDATE','DELETE','TRUNCATE']) ps(p)),
 'triggers',(SELECT coalesce(jsonb_agg(jsonb_build_object('table',tgrelid::regclass::text,'def',pg_get_triggerdef(oid)) ORDER BY tgrelid::regclass::text,tgname),'[]'::jsonb) FROM pg_trigger WHERE tgrelid IN ('public.event_participants'::regclass,'public.rounds'::regclass,'public.matches'::regclass,'public.match_players'::regclass,'public.match_results'::regclass) AND NOT tgisinternal),
 'existing_functions',(SELECT jsonb_agg(jsonb_build_object('function',p.oid::regprocedure::text,'owner',p.proowner::regrole::text,'definer',p.prosecdef,'hash',md5(replace(pg_get_functiondef(p.oid),chr(13),''))) ORDER BY p.oid::regprocedure::text) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE (n.nspname='public' AND p.proname IN ('is_super_user','can_manage_friendly_team_event_by_sides')) OR (n.nspname='profile_link_private' AND p.proname IN ('guard_reference','merge_profiles')) OR n.nspname IN ('events_identity_private','participants_identity_private')),
 'new_function',(SELECT jsonb_agg(jsonb_build_object('function',p.oid::regprocedure::text,'definer',p.prosecdef,'config',p.proconfig,'hash',md5(replace(pg_get_functiondef(p.oid),chr(13),'')))) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='match_identity_private'),
 'constraints_hash',(SELECT md5(jsonb_agg(jsonb_build_object('table',conrelid::regclass::text,'def',pg_get_constraintdef(oid)) ORDER BY conrelid::regclass::text,conname)::text) FROM pg_constraint WHERE conrelid IN ('public.event_participants'::regclass,'public.rounds'::regclass,'public.matches'::regclass,'public.match_players'::regclass,'public.match_results'::regclass)),
 'other_policies_hash',(SELECT md5(coalesce(jsonb_agg(to_jsonb(p) ORDER BY tablename,policyname)::text,'')) FROM pg_policies p WHERE schemaname='public' AND tablename NOT IN ('event_participants','rounds','matches','match_players','match_results')),
 'other_acl_hash',(SELECT md5(jsonb_agg(jsonb_build_object('table',c.relname,'acl',c.relacl::text) ORDER BY c.relname)::text) FROM pg_class c WHERE c.relnamespace='public'::regnamespace AND c.relkind IN ('r','p','v','m','f') AND c.oid NOT IN ('public.event_participants'::regclass,'public.rounds'::regclass,'public.matches'::regclass,'public.match_players'::regclass,'public.match_results'::regclass))
) AS evidence;
COMMIT;
